mapper.select:
SELECT p.*, d1.name AS doctor_name, d2.name AS first_doctor_name, s.source_name, (SELECT GROUP_CONCAT(t.tag_name) FROM t_patient_tag_rel r LEFT JOIN t_patient_tag t ON r.tag_id = t.id AND t.is_delete = 0 WHERE r.patient_id = p.id) AS tag_names FROM t_patient p LEFT JOIN t_employee d1 ON p.doctor_id = d1.id AND d1.is_delete = 0 LEFT JOIN t_employee d2 ON p.first_doctor_id = d2.id AND d2.is_delete = 0 LEFT JOIN t_patient_source s ON p.source_id = s.id AND s.is_delete = 0 WHERE p.is_delete = 0
AND p.clinic_id = #{clinicId}
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.mobile LIKE CONCAT('%', #{keyword}, '%') OR p.medical_record_no LIKE CONCAT('%', #{keyword}, '%') OR p.name_pinyin LIKE CONCAT('%', #{keyword}, '%'))
AND p.doctor_id = #{doctorId}
AND p.first_doctor_id = #{firstDoctorId}
AND EXISTS ( SELECT 1 FROM t_patient_tag_rel r WHERE r.patient_id = p.id AND r.tag_id = #{tagId} )
ORDER BY p.id DESC
